"""Generated by tools/gen_metaballs_asm.py: edit that.

frame_asm(args_address): one whole 2D metaballs frame, bit-identical to
metaballs.render(). Relabelled as viper by tools/asm_to_viper.py, so the
argument object is at [r3].
"""

import micropython


@micropython.asm_thumb
def frame_asm(r0, r1, r2, r3):
    ldr(r7, [r3, 0])
    push({r7})
    asr(r7, r7, 1)
    mov(r3, r8)  # r8-r11 belong to the caller
    mov(r4, r9)
    mov(r5, r10)
    mov(r6, r11)
    push({r3, r4, r5, r6})

    # clear the row sums (the shading below keeps them clear)
    ldr(r1, [r7, 40])
    ldr(r2, [r7, 44])
    mov(r0, 0)
    label(clear)
    str(r0, [r1, 0])
    add(r1, 4)
    cmp(r1, r2)
    blt(clear)

    label(row)
    ldr(r6, [r7, 48])
    str(r6, [r7, 56])
    ldr(r3, [r7, 52])
    cmp(r6, r3)
    bge_w(shade)

    label(ball)
    ldr(r6, [r7, 56])
    # dy = y16 - ball y; h2 = r2 - dy * dy
    ldr(r3, [r6, 4])
    ldr(r4, [r7, 64])
    sub(r4, r4, r3)
    mov(r10, r4)
    mov(r3, r4)
    mul(r3, r4)
    ldr(r5, [r6, 12])
    sub(r5, r5, r3)
    ble_w(ball_next)
    mov(r8, r5)
    ldr(r3, [r6, 16])
    mov(r9, r3)
    # columns x0..x1 of the ball's bounding span, clipped to the row
    ldr(r0, [r6, 0])
    ldr(r1, [r6, 8])
    sub(r2, r0, r1)
    asr(r2, r2, 4)
    bpl(x0_ok)
    mov(r2, 0)
    label(x0_ok)
    add(r3, r0, r1)
    asr(r3, r3, 4)
    ldr(r5, [r7, 0])
    sub(r5, r5, 1)
    cmp(r3, r5)
    ble(x1_ok)
    mov(r3, r5)
    label(x1_ok)
    sub(r3, r3, r2)
    add(r3, r3, 1)
    ble_w(ball_next)
    # dx = (x0 << 4) + 8 - x; pointer = row + x0 * 12
    lsl(r4, r2, 4)
    add(r4, 8)
    sub(r0, r4, r0)
    lsl(r4, r2, 2)
    lsl(r5, r2, 3)
    add(r4, r4, r5)
    ldr(r1, [r7, 40])
    add(r1, r1, r4)
    mov(r2, r3)

    # r0 dx, r1 the column's sums, r2 columns left; r8 h2, r9 inv, r10 dy
    label(column)
    mov(r3, r0)
    mul(r3, r0)
    mov(r4, r8)
    sub(r4, r4, r3)
    ble(column_next)
    mov(r3, r9)
    mul(r4, r3)
    asr(r4, r4, 16)  # qn: 1 - d^2/R^2, 12 fractional bits
    mov(r3, r4)
    mul(r3, r4)
    asr(r3, r3, 12)
    ldr(r5, [r1, 0])
    add(r5, r5, r3)
    str(r5, [r1, 0])
    mov(r3, r4)
    mul(r3, r0)
    asr(r3, r3, 4)
    mov(r5, r9)
    mul(r3, r5)
    asr(r3, r3, 16)
    ldr(r5, [r1, 4])
    add(r5, r5, r3)
    str(r5, [r1, 4])
    mov(r3, r4)
    mov(r5, r10)
    mul(r3, r5)
    asr(r3, r3, 4)
    mov(r5, r9)
    mul(r3, r5)
    asr(r3, r3, 16)
    ldr(r5, [r1, 8])
    add(r5, r5, r3)
    str(r5, [r1, 8])
    label(column_next)
    add(r0, 16)
    add(r1, 12)
    sub(r2, r2, 1)
    bgt(column)

    label(ball_next)
    ldr(r6, [r7, 56])
    add(r6, 20)
    str(r6, [r7, 56])
    ldr(r3, [r7, 52])
    cmp(r6, r3)
    blt_w(ball)

    # shade the row: r0 the pixel, r1 the column's sums, r2 columns left;
    # r8 threshold, r9 tables, r10 slope shift, r11 glow shift
    label(shade)
    ldr(r3, [r7, 12])
    mov(r8, r3)
    ldr(r3, [r7, 36])
    mov(r9, r3)
    ldr(r3, [r7, 20])
    mov(r10, r3)
    ldr(r3, [r7, 16])
    mov(r11, r3)
    ldr(r0, [r7, 32])
    ldr(r1, [r7, 40])
    ldr(r2, [r7, 0])
    label(pixel)
    ldr(r3, [r1, 0])
    cmp(r3, 0)
    bne(lit)
    # no field here (most of the screen): the glow palette's first color
    mov(r4, r9)
    ldrh(r4, [r4, 0])
    strh(r4, [r0, 0])
    b(pixel_next)
    label(lit)
    ldr(r4, [r1, 4])
    ldr(r5, [r1, 8])
    mov(r6, 0)
    str(r6, [r1, 0])
    str(r6, [r1, 4])
    str(r6, [r1, 8])
    mov(r6, r8)
    cmp(r3, r6)
    blt_w(outside)
    # inside: slope = gradient * scale[(f - threshold) >> 3] >> slope shift
    sub(r3, r3, r6)
    asr(r3, r3, 3)
    cmp(r3, 255)
    ble(t_ok)
    mov(r3, 255)
    label(t_ok)
    lsl(r3, r3, 1)
    mov(r6, r9)
    add(r3, r3, r6)
    movw(r6, 8704)
    add(r3, r3, r6)
    ldrh(r3, [r3, 0])
    mov(r6, r10)
    mul(r4, r3)
    asr(r4, r6)
    add(r4, 32)
    bpl(gx_low_ok)
    mov(r4, 0)
    label(gx_low_ok)
    cmp(r4, 63)
    ble(gx_ok)
    mov(r4, 63)
    label(gx_ok)
    mul(r5, r3)
    asr(r5, r6)
    add(r5, 32)
    bpl(gy_low_ok)
    mov(r5, 0)
    label(gy_low_ok)
    cmp(r5, 63)
    ble(gy_ok)
    mov(r5, 63)
    label(gy_ok)
    lsl(r5, r5, 7)
    lsl(r4, r4, 1)
    add(r5, r5, r4)
    mov(r6, r9)
    add(r5, r5, r6)
    movw(r6, 512)
    add(r5, r5, r6)
    ldrh(r5, [r5, 0])
    strh(r5, [r0, 0])
    b(pixel_next)
    label(outside)
    mov(r6, r11)
    asr(r3, r6)
    cmp(r3, 255)
    ble(g_ok)
    mov(r3, 255)
    label(g_ok)
    lsl(r3, r3, 1)
    mov(r6, r9)
    add(r3, r3, r6)
    ldrh(r3, [r3, 0])
    strh(r3, [r0, 0])
    label(pixel_next)
    add(r0, 2)
    add(r1, 12)
    sub(r2, r2, 1)
    bgt_w(pixel)
    str(r0, [r7, 32])

    # next row
    ldr(r3, [r7, 64])
    add(r3, 16)
    str(r3, [r7, 64])
    ldr(r3, [r7, 60])
    add(r3, 1)
    str(r3, [r7, 60])
    ldr(r4, [r7, 4])
    cmp(r3, r4)
    blt_w(row)

    pop({r3, r4, r5, r6})
    mov(r8, r3)
    mov(r9, r4)
    mov(r10, r5)
    mov(r11, r6)
    pop({r0})
